using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace RPG.EditorTools
{
    /// <summary>
    /// Creates Assets/Scenes/World.unity: just the player, the follow camera, the save system and a sun.
    /// Everything else (terrain, towns, monsters) is generated by RPG.World.WorldBuilder when it loads.
    /// </summary>
    public static class RpgWorldSetup
    {
        public const string ScenePath = "Assets/Scenes/World.unity";

        [MenuItem("RPG/Create World Scene")]
        public static void CreateFromMenu()
        {
            Create();
        }

        public static void EnsureScene()
        {
            if (AssetDatabase.LoadAssetAtPath<SceneAsset>(ScenePath) == null) Create();
        }

        public static void Create()
        {
            Scene scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

            GameObject sunObject = new GameObject("Sun");
            Light sun = sunObject.AddComponent<Light>();
            sun.type = LightType.Directional;
            sun.intensity = 1.0f;
            sun.color = new Color(1f, 0.96f, 0.88f);
            sun.shadows = LightShadows.Soft;
            sun.shadowStrength = 0.75f;
            sunObject.transform.rotation = Quaternion.Euler(50f, -30f, 0f);
            RenderSettings.sun = sun;
            RenderSettings.skybox = AssetDatabase.GetBuiltinExtraResource<Material>("Default-Skybox.mat");
            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Trilight;
            Lightmapping.giWorkflowMode = Lightmapping.GIWorkflowMode.OnDemand;

            GameObject player = Instantiate("Assets/Game/Characters/Player.prefab");
            player.transform.position = new Vector3(0, 2, -177);
            var saveable = player.GetComponent<RPG.Saving.SaveableEntity>();
            if (saveable != null)
            {
                SerializedObject so = new SerializedObject(saveable);
                so.FindProperty("uniqueIdentifier").stringValue = "player";
                so.ApplyModifiedPropertiesWithoutUndo();
            }

            GameObject camera = Instantiate("Assets/Game/Core/FollowCamera.prefab");
            var follow = camera.GetComponent<RPG.Core.FollowCamera>();
            if (follow != null)
            {
                SerializedObject so = new SerializedObject(follow);
                so.FindProperty("target").objectReferenceValue = player.transform;
                so.ApplyModifiedPropertiesWithoutUndo();
            }
            Instantiate("Assets/Game/Core/Saving.prefab");

            EditorSceneManager.SaveScene(scene, ScenePath);
            Debug.Log("[RPG World] created " + ScenePath);
        }

        static GameObject Instantiate(string path)
        {
            GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (prefab == null)
            {
                Debug.LogError("[RPG World] missing prefab " + path);
                return new GameObject(System.IO.Path.GetFileNameWithoutExtension(path));
            }
            return (GameObject)PrefabUtility.InstantiatePrefab(prefab);
        }
    }
}
